def solve_a(N):
    a = {1: 0}
    for n in range(2, N + 1):
        max_val = -float('inf')
        for i in range(1, n):
            # i goes from 1 to n-1
            # n-i goes from n-1 to 1

            # We need a_i and a_{n-i}
            if i not in a or (n - i) not in a:
                # This should not happen if we calculate iteratively
                print(f"Error: a[{i}] or a[{n-i}] not computed yet for n={n}")
                return None

            term = a[i] + a[n - i] + min(i, n - i)

            if term > max_val:
                max_val = term

        a[n] = max_val
    return a

