def solve_a_n(N):
    # Initial values from notes.md
    a = {1: 0, 2: 1, 3: 2, 4: 4, 5: 5, 6: 7}

    def get_a(n):
        if n in a:
            return a[n]
        if n < 1:
            raise ValueError("Index must be positive")

        # Recurrence relations
        if n % 2 == 0:
            k = n // 2
            # a_n = 2*a_k + k
            result = 2 * get_a(k) + k
        else:
            k = (n - 1) // 2
            # a_n = a_k + a_{k+1} + k
            result = get_a(k) + get_a(k + 1) + k

        a[n] = result
        return result

